async function streamAgentResponse(messages: UIMessage[]) {
  const modelMessages = convertToModelMessages(messages);

  const result = true
    ? streamText({
        model: getModel(),
        system: REACT_AGENT_SYSTEM_PROMPT,
        messages: modelMessages,
        tools: {
          page_action: pageActionTool,
          chrome_api: chromeApiTool,
        },
        stopWhen: stepCountIs(100),
        onChunk: ({ chunk }) => {
          console.log('[Stream Chunk]', chunk.type, JSON.stringify(chunk, null, 2));
        },
        onError: ({ error }) => {
          console.error('[Agent] Stream error:', error);
        },
        onStepFinish: async ({ toolCalls, finishReason, response }) => {
          console.log('[Agent] Step finished:', {
            finishReason,
            toolCallsCount: toolCalls?.length || 0,
            toolNames: toolCalls?.map(tc => tc.toolName),
          });
          if (toolCalls && toolCalls.length > 0) {
            toolCalls.forEach((tc, idx) => {
              console.log(`[Agent] Tool call ${idx + 1}:`, {
                name: tc.toolName,
                input: JSON.stringify(tc),
              });
            });
          }
        },
        onFinish: ({ finishReason, usage, response }) => {
          console.log('[Agent] Stream finished:', JSON.stringify({
            finishReason,
            usage,
            responseId: response?.id,
          }, null, 2));
        },
      })
    : streamText({
        model: getModel(),
        system: AGENT_SYSTEM_PROMPT,
        messages: modelMessages,
        tools: {
          generateSteps: generateStepsTool,
          generateScript: generateScriptTool,
          executeWorkflow: executeWorkflowTool,
        },
        stopWhen: stepCountIs(10),
        onChunk: ({ chunk }) => {
          console.log('[Stream Chunk]', chunk.type, JSON.stringify(chunk, null, 2));
        },
        onError: ({ error }) => {
          console.error('[Agent] Stream error:', error);
        },
        onStepFinish: async ({ toolCalls, finishReason, response }) => {
          console.log('[Agent] Step finished:', {
            finishReason,
            toolCallsCount: toolCalls?.length || 0,
            toolNames: toolCalls?.map(tc => tc.toolName),
          });
          if (toolCalls && toolCalls.length > 0) {
            toolCalls.forEach((tc, idx) => {
              console.log(`[Agent] Tool call ${idx + 1}:`, {
                name: tc.toolName,
                input: JSON.stringify(tc),
              });
            });
          }
        },
        onFinish: ({ finishReason, usage, response }) => {
          console.log('[Agent] Stream finished:', JSON.stringify({
            finishReason,
            usage,
            responseId: response?.id,
          }, null, 2));
        },
      });

  return result;
}

