async function ensureOffscreenDocument() {
  if ((chrome as any).runtime.getContexts) {
    const existingContexts = await (chrome as any).runtime.getContexts({
      contextTypes: ['OFFSCREEN_DOCUMENT'],
    });

    if (existingContexts.length > 0) {
      return;
    }
  }

  if (offscreenCreating) {
    await offscreenCreating;
    return;
  }

  offscreenCreating = (chrome as any).offscreen.createDocument({
    url: 'src/offscreen/index.html',
    reasons: ['DOM_SCRAPING'],
    justification: 'Execute Chrome API scripts dynamically',
  });

  await offscreenCreating;
  offscreenCreating = null;
}

src.background.executors.chromeApi.execu.source_code:
async function executeChromeApi(script: string): Promise<ChromeApiOutput> {
  try {
    await ensureOffscreenDocument();

    const response = await chrome.runtime.sendMessage({
      type: 'EXECUTE_CHROME_API',
      script,
    });

    if (response.success) {
      return {
        success: true,
        data: response.data,
      };
    } else {
      return {
        success: false,
        error: response.error,
      };
    }
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    console.error('[ChromeApi Executor] Error:', errorMessage);

    return {
      success: false,
      error: errorMessage,
    };
  }
}

