function handlePageAgentResult(
  toolCallId: string,
  result: { success: boolean; data?: unknown; error?: string },
) {
  const pending = pendingExecutions.get(toolCallId);
  if (!pending) {
    console.warn(
      "[PageAction Executor] No pending execution for toolCallId:",
      toolCallId,
    );
    return;
  }

  pending.resolve({
    success: result.success,
    data: result.data,
    error: result.error,
    logs: pending.logs,
  });

  pendingExecutions.delete(toolCallId);
}

function handlePageAgentLog(toolCallId: string, log: PageAgentLogEntry) {
  const pending = pendingExecutions.get(toolCallId);
  if (pending) {
    pending.logs.push(log);
  }
}

src.background.executors.pageAction.exec.source_code:
async function executePageAction(
  ctx: PageActionContext,
): Promise<PageActionOutput> {
  const { tabId, instruction, toolCallId } = ctx;

  try {
    const tab = await chrome.tabs.get(tabId);

    if (!isInjectablePage(tab.url)) {
      return {
        success: false,
        error: "无法在此页面执行（浏览器内置页面不支持）",
      };
    }

    await ensureContentScriptReady(tabId);
    await waitForPageReady(tabId);

    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        pendingExecutions.delete(toolCallId);
        resolve({
          success: false,
          error: "PageAgent execution timed out (60s)",
        });
      }, 60000);

      pendingExecutions.set(toolCallId, {
        resolve: (output) => {
          clearTimeout(timeout);
          chrome.tabs
            .get(tabId)
            .then((currentTab) => {
              output.pageState = {
                url: currentTab.url || "",
                title: currentTab.title || "",
              };
              resolve(output);
            })
            .catch(() => {
              resolve(output);
            });
        },
        reject: (error) => {
          clearTimeout(timeout);
          reject(error);
        },
        logs: [],
      });

      chrome.scripting
        .executeScript({
          target: { tabId },
          files: ["page-agent-init.js"],
          world: "MAIN",
        })
        .then(() => {
          console.log(
            "[PageAction Executor] PageAgent script injected, sending instruction",
          );

          chrome.scripting.executeScript({
            target: { tabId },
            func: (instr: string, tcId: string) => {
              const checkAndExecute = () => {
                const agent = (window as any).pageAgent;
                if (agent?.execute) {
                  console.log("[PageAction] Executing instruction:", instr);
                  agent
                    .execute(instr)
                    .then((result: any) => {
                      window.postMessage(
                        {
                          source: "PILOT_PAGE_ACTION",
                          type: "PAGE_ACTION_COMPLETE",
                          toolCallId: tcId,
                          result: {
                            success: result.success,
                            data: result.data,
                            error: result.success
                              ? undefined
                              : result.data || "Unknown error",
                          },
                        },
                        "*",
                      );
                    })
                    .catch((err: Error) => {
                      window.postMessage(
                        {
                          source: "PILOT_PAGE_ACTION",
                          type: "PAGE_ACTION_COMPLETE",
                          toolCallId: tcId,
                          result: {
                            success: false,
                            error: err.message,
                          },
                        },
                        "*",
                      );
                    });
                } else {
                  setTimeout(checkAndExecute, 100);
                }
              };
              checkAndExecute();
            },
            args: [instruction, toolCallId],
            world: "MAIN",
          });
        })
        .catch((err) => {
          clearTimeout(timeout);
          pendingExecutions.delete(toolCallId);
          resolve({
            success: false,
            error: `Failed to inject PageAgent: ${err.message}`,
          });
        });
    });
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      error: errorMessage,
    };
  }
}

src.background.managers.navigation.setup.source_code:
function setupNavigationListeners() {
  // 监听导航开始事件
  chrome.webNavigation.onCommitted.addListener((details) => {
    if (details.frameId !== 0) return;

    const tabId = details.tabId;
    const workflow = workflowManager.getWorkflow(tabId);

    if (workflow && workflow.status === 'running') {
      console.log(`[Pilot Engine] Navigation detected in Tab ${tabId}: ${details.url}`);
    }
  });

  // 监听 History State 更新（SPA 内导航）
  chrome.webNavigation.onHistoryStateUpdated.addListener((details) => {
    if (details.frameId !== 0) return;

    const tabId = details.tabId;
    const workflow = workflowManager.getWorkflow(tabId);

    if (workflow && workflow.status === 'running') {
      console.log(`[Pilot Engine] History state updated in Tab ${tabId}: ${details.url}`);
    }
  });
}

src.background.managers.page-ready.Ready.source_code:
interface ReadyResolver {
  resolve: () => void;
  reject: (reason: string) => void;
  requiredEvents: Set<ReadyEventType>;
  receivedEvents: Set<ReadyEventType>;
  timeout?: ReturnType<typeof setTimeout>;
}

src.background.managers.page-ready.waitF.source_code:
function waitForPageReady(tabId: number, requiredEvents: ReadyEventType[] = ['PAGE_FULLY_READY'], timeoutMs: number = 6000): Promise<void> {
  // 如果已有等待中的 resolver，先清理它
  const existingResolver = readyResolvers.get(tabId);
  if (existingResolver) {
    if (existingResolver.timeout) clearTimeout(existingResolver.timeout);
    existingResolver.reject('Cancelled by new ready wait request');
    readyResolvers.delete(tabId);
  }

  return new Promise((resolve, reject) => {
    const resolver: ReadyResolver = {
      resolve,
      reject,
      requiredEvents: new Set(requiredEvents),
      receivedEvents: new Set(),
      timeout: setTimeout(() => {
        readyResolvers.delete(tabId);
        const msg = `Page ready timeout (${timeoutMs}ms) for tab ${tabId}. Required: ${requiredEvents.join(', ')}`;
        console.error(`[Pilot Engine] ${msg}`);
        reject(msg);
      }, timeoutMs)
    };

    readyResolvers.set(tabId, resolver);
    console.log(`[Pilot Engine] Waiting for page ready in Tab ${tabId}:`, requiredEvents);
  });
}

src.background.managers.page-ready.handl.source_code:
function handleReadyEvent(event: ReadyEvent) {
  const { tabId, type } = event;
  console.log(`[Pilot Engine] Ready event received: ${type} for Tab ${tabId}`);

  const resolver = readyResolvers.get(tabId);
  if (!resolver) {
    console.log(`[Pilot Engine] No resolver found for Tab ${tabId}, ignoring event`);
    return;
  }

  resolver.receivedEvents.add(type);
  console.log(`[Pilot Engine] Tab ${tabId} - required: [${Array.from(resolver.requiredEvents)}], received: [${Array.from(resolver.receivedEvents)}]`);

  // 检查是否所有必需的事件都已收到
  const allReceived = Array.from(resolver.requiredEvents).every(e => resolver.receivedEvents.has(e));

  if (allReceived) {
    if (resolver.timeout) clearTimeout(resolver.timeout);
    readyResolvers.delete(tabId);
    console.log(`[Pilot Engine] Page fully ready in Tab ${tabId}`);
    resolver.resolve();
  }
}

