async function loadMessages(serverUrl: string, chatId: string): Promise<UIMessage[]> {
  const res = await fetch(`${serverUrl}/api/conversations/${chatId}`);
  if (!res.ok) return [];
  const data = await res.json();
  return (data.messages || []).map((m: any) => ({
    id: m.id,
    role: m.role,
    parts: m.parts,
  }));
}

