function Chat({ chatId, isNewChat, serverUrl, initialMessages, onConversationCreated }: ChatProps) {
  const [input, setInput] = useState('');

  const transport = useMemo(() => new DefaultChatTransport({
    api: `${serverUrl}/api/chat`,
    prepareSendMessagesRequest({ messages }) {
      return { body: { message: messages[messages.length - 1], id: chatId } };
    },
  }), [serverUrl, chatId]);

  const { messages, sendMessage, status, error, setMessages, addToolOutput } = useChat({
    id: chatId,
    messages: initialMessages,
    transport,
    // Automatically send request when all tool results are available
    sendAutomaticallyWhen: lastAssistantMessageIsCompleteWithToolCalls,
    async onToolCall({ toolCall }) {
      console.log('[Chat] onToolCall:', toolCall.toolName, toolCall);
      // Client-side tool handling will be done in useWorkflowExecution
    },
  });

  const isLoading = status === 'streaming' || status === 'submitted';

  useEffect(() => {
    if (isNewChat && status === 'streaming') {
      onConversationCreated?.(chatId);
    }
  }, [status, isNewChat, chatId, onConversationCreated]);

  useWorkflowExecution(messages, initialMessages, setMessages, addToolOutput);
  usePageAction(messages, initialMessages, setMessages, addToolOutput);
  useChromeApi(messages, initialMessages, setMessages, addToolOutput);

  const handleSubmit = () => {
    if (!input.trim() || isLoading) return;
    sendMessage({ role: 'user', parts: [{ type: 'text', text: input }] });
    setInput('');
  };

  return (
    <div className="flex flex-col h-full relative bg-slate-50">
      {error && (
        <div className="absolute top-0 left-0 right-0 z-10 p-2 bg-red-50 text-red-600 text-xs border-b border-red-100">
          Error: {error.message}
        </div>
      )}

src.components.agent.chat.ChatMessage.Ch.source_code:
interface ChatMessageProps {
  message: UIMessage;
  isStreaming?: boolean;
}

function ChatMessage({ message, isStreaming = false }: ChatMessageProps) {
  const isUser = message.role === 'user';

  if (isUser) {
    return (
      <Message className="justify-end">
        {message.parts?.map((part, idx) => {
          if (part.type === 'text') {
            return (
              <MessageContent
                key={idx}
                className="bg-primary text-primary-foreground max-h-[240px] overflow-y-auto"
              >
                {part.text}
              </MessageContent>
            );
          }
          return null;
        })}
      </Message>
    );
  }

  return (
    <Message>
      <div className="flex flex-col gap-2 flex-1 min-w-0">
        {message.parts?.map((part, idx) => {
          if (part.type === 'text') {
            return (
              <MessageContent
                key={idx}
                markdown
                className="bg-transparent"
              >
                {part.text}
              </MessageContent>
            );
          }

          if (isToolOrDynamicToolUIPart(part)) {
            return (
              <Tool
                key={idx}
                toolPart={part}
                defaultOpen={isStreaming}
              />
            );
          }

          return null;
        })}
      </div>
    </Message>
  );
}

