src.offscreen.offscreen.createChromeProx.source_code:
function createChromeProxy(): typeof chrome {
  return new Proxy({} as any, {
    get(_target, namespace: string) {
      if (namespace === 'runtime') {
        return chrome.runtime;
      }

      return new Proxy({}, {
        get(_target, method: string) {
          return async (...args: any[]) => {
            const callId = callIdCounter++;

            return new Promise((resolve, reject) => {
              pendingCalls.set(callId, { resolve, reject });

              chrome.runtime.sendMessage({
                type: 'CHROME_API_CALL',
                callId,
                namespace,
                method,
                args: JSON.parse(JSON.stringify(args)),
              });

              setTimeout(() => {
                if (pendingCalls.has(callId)) {
                  pendingCalls.delete(callId);
                  reject(new Error(`Chrome API call timeout: ${namespace}.${method}`));
                }
              }, 30000);
            });
          };
        }
      });
    }
  });
}

src.offscreen.offscreen.executeScript.source_code:
async function executeScript(script: string): Promise<unknown> {
  try {
    const chromeProxy = createChromeProxy();
    const AsyncFunction = Object.getPrototypeOf(async function(){}).constructor;
    const fn = new AsyncFunction('chrome', `return (async () => { ${script} })()`);
    const result = await fn(chromeProxy);
    return result;
  } catch (error) {
    console.error('[Offscreen] Script execution error:', error);
    throw error;
  }
}

